package com.bankScraper.bank

import com.bankScraper.*
import com.constants.AppConstant
import com.giaybac.traprange.entity.Table
import org.apache.commons.lang.StringUtils
import org.jsoup.Jsoup
import org.jsoup.nodes.Element
import org.jsoup.select.Elements

import java.text.ParseException
import java.text.SimpleDateFormat

class AndhraBankUtil {

    public
    static BankTransactionCategory calculateCorporateBankTransactionCategory(BankTransactionResponse transaction) {
        Map<BankTransactionCategory, String> patternMap = [:]
        patternMap.put(BankTransactionCategory.ATM_WITHDRAWAL, "atm\\s*wdl|^nfs")
        patternMap.put(BankTransactionCategory.CARD_PAYMENT, "vps/|ips/|ccard")
        patternMap.put(BankTransactionCategory.CASH_DEPOSIT, "^cash|/cash/|by\\s*cash")
        patternMap.put(BankTransactionCategory.INTERNET_FUND_TRANSFER, "^by\\s*tfr")
        patternMap.put(BankTransactionCategory.OPENING_BALANCE, "^opening\\sbalance\$")
        patternMap.put(BankTransactionCategory.CASH_WITHDRAW, "^self\$")
        patternMap.put(BankTransactionCategory.CHEQUE_PAID, "^to\\s*cts\\s*clg")
        patternMap.put(BankTransactionCategory.CHEQUE_BOUNCE, "^inward\\s*reject|^reject|^ow\\s*clg\\s*reject")
        patternMap.put(BankTransactionCategory.CHEQUE_COLLECTION, "^inst\\s*[0-9]{5,6}\\s*clg")
        patternMap.put(BankTransactionCategory.CHARGES, "fee|chrg|charges")
        patternMap.put(BankTransactionCategory.TAX, "service\\s*tax")

        BankTransactionCategory transactionCategory = BankUtil.calculateTransactionCategory(patternMap, transaction)
        return transactionCategory
    }

    public
    static String extractAccountHolderName(List<String> header, ProcessedBankStatementVO processedBankStatementVO) {
        String accountHolder = ""
        for (int lineNumber = 0; (lineNumber < header.size() && !accountHolder); lineNumber++) {
            try {
                String line = header.get(lineNumber)
                if (StringUtils.isBlank(line)) {
                    continue
                } else if (line.find("Name")) {
                    if (line.find("Account[\\s]*Name")) {
                        accountHolder = line.split("Account[\\s]*Name[\\s]*:")[1]
                    } else {
                        line = header.get(lineNumber - 1)
                        accountHolder = line?.replaceAll("Name", "")
                    }
                } else if (line?.find("ACCOUNT[\\s]*NAME")) {
                    accountHolder = line?.find("(?<=NAME\\s).*(?=\\sSOL)")?.trim()
                } else if (line.find("Phone[\\s]*Number[\\s]*:[\\s]*:[\\s]*[0-9]+")) {
                    accountHolder = ++lineNumber < header.size() ? header.get(lineNumber) : ""
                }
            }
            catch (Exception e) {
                println("== ERROR : An exception occurred while extracting ACCOUNT_HOLDER_NAME for ${processedBankStatementVO.processBankStatementCO.bank} bank ==> " + e)
                e.printStackTrace()
            }
        }
        accountHolder.trim()
    }

    public static void extractTransactionsFromCurrentAccount(ProcessedBankStatementVO processedBankStatementVO) {
        String password = processedBankStatementVO.processBankStatementCO.password
        List<SimpleDateFormat> dateFormats = [new SimpleDateFormat("dd/MM/yy"), new SimpleDateFormat("dd-MMM-yyyy")]
        List<File> pdfFiles = HelperMethod.splitPdfDocument(processedBankStatementVO.processBankStatementCO.bankStatement, password)
        Integer count = 0
        Boolean firstDescriptionThenChqColumn = Boolean.FALSE
        while (count < pdfFiles.size()) {
            File file = pdfFiles.get(count)
            List<Table> tables = HelperMethod.getPDFTableList(file, password, null, null)
            String html = tables.get(0).toHtml()
            Integer firstTableIndex = -1
            Integer lastTableIndex = -1
            Integer lastPageSize = 0
            org.jsoup.nodes.Document document = Jsoup.parse(html)
            if (!document.select("table").empty) {
                document.select("tr").eachWithIndex { tr, index ->
                    if (tr.text().find("Transaction[\\s]*Description|(Particulars[\\s]*Chq[\\s]*No)")) {
                        firstTableIndex = index
                    } else if (tr.text().find("Grand[\\s]*Total")) {
                        lastTableIndex = index - 1
                    }
                }
                lastPageSize = document.select("tr").size()
            }
            lastTableIndex = lastTableIndex >= 0 ? lastPageSize - lastTableIndex : -1
            List<Table> finalTables = []
            if (firstTableIndex >= 0 && lastTableIndex >= 0) {
                int[] exceptLinesFirstPage = (0..firstTableIndex - 1)
                int[] exceptLinesLastPage = (-1..-(lastTableIndex - 1))
                finalTables = HelperMethod.getPDFTableList(file, password, exceptLinesFirstPage, exceptLinesLastPage)
            } else {
                int[] exceptLinesFirstPage = (0..firstTableIndex - 1)
                int[] exceptLinesMedianPages = []
                int[] exceptLinesLastPage = (-1..-(lastTableIndex - 1))
                def exceptLineArr = firstTableIndex >= 0 ? exceptLinesFirstPage : (lastTableIndex >= 0 ? exceptLinesLastPage : exceptLinesMedianPages)
                finalTables = HelperMethod.getPDFTableList(file, password, exceptLineArr, null)
            }
            String finalHTML = finalTables.empty ? "" : finalTables.get(0).toHtml()
            org.jsoup.nodes.Document htmlDocuemnt = Jsoup.parse(finalHTML)
            if (!htmlDocuemnt.select("table").empty) {
                Elements elements = htmlDocuemnt.select("tr")
                Element firstTableHeader = elements.get(0)
                if (firstTableHeader.hasText() && firstTableHeader.text().find("Transaction[\\s]*Description")) {
                    elements.remove(0)
                } else if (firstTableHeader.hasText() && firstTableHeader.text().find("Particulars[\\s]*Chq[\\s]*No")) {
                    elements.remove(0)
                    firstDescriptionThenChqColumn = Boolean.TRUE
                }
                if (!processedBankStatementVO.bankTransactionList && elements?.first()?.text()?.find("B/F")) {
                    String amount = elements.first().text().find(AppConstant.currencyRegex)
                    Double openingBalance = HelperMethod.getSanitizeDouble(amount)
                    processedBankStatementVO.bankTransactionList << BankUtil.createOpeningBalanceTransaction(openingBalance)
                    elements.remove(0)
                }
                Integer columnCount = elements ? elements.first().select("td").size() : 0
                Integer dateIndex = 0
                Integer balanceIndex = columnCount - 1
                Integer creditIndex = balanceIndex - 1
                Integer debitIndex = balanceIndex - 2
                Integer remarkIndex = dateIndex + 1
                Integer descriptionIndex = dateIndex + 2
                if (firstDescriptionThenChqColumn) {
                    remarkIndex = dateIndex + 2
                    descriptionIndex = dateIndex + 1
                }
                Integer elementCount = elements ? elements.size() : 0
                Integer tempCount = 0
                while (tempCount < elementCount) {
                    String date = ""
                    StringBuilder description = new StringBuilder("")
                    String amount = ""
                    String type = ""
                    String balance = ""
                    Element element = elements.get(tempCount)
                    date = element.select("td").eq(dateIndex).text()
                    if (StringUtils.isNotBlank(date) && StringUtils.isNotEmpty(date)) {
                        description.append(element.select("td").eq(descriptionIndex).text())
                        Integer tempDescCount = 1
                        while (tempCount + tempDescCount < elements.size() && StringUtils.isBlank(elements.get(tempCount + tempDescCount).select("td").eq(balanceIndex).text())) {
                            Element tempElement = elements.get(tempCount + tempDescCount)
                            if (tempElement.select("td").eq(descriptionIndex).hasText())
                                description.append(" " + tempElement.select("td").eq(descriptionIndex).text())
                            tempDescCount += 1
                        }
                        amount = element.select("td").eq(creditIndex).text() ? element.select("td").eq(creditIndex).text() : element.select("td").eq(debitIndex).text()
                        type = element.select("td").eq(debitIndex).text() ? Enums.BankTransactionType.DEBIT.toString() : Enums.BankTransactionType.CREDIT.toString()
                        balance = element.select("td").eq(balanceIndex).text()
                        try {
                            BankTransactionResponse transactionResponse = new BankTransactionResponse()
                            for (SimpleDateFormat format : dateFormats) {
                                try {
                                    transactionResponse.transactionDate = format.parse(date)
                                } catch (ParseException pe) {
                                }
                            }
                            transactionResponse.description = description.toString()
                            transactionResponse.amount = HelperMethod.getSanitizeDouble(amount)
                            transactionResponse.type = type
                            transactionResponse.balanceAfterTransaction = BankUtil.processBalanceAmount(balance)
                            transactionResponse.remark = element.select("td").eq(remarkIndex).text()
                            processedBankStatementVO.bankTransactionList << transactionResponse
                        } catch (Exception e) {
                            processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.TRANSACTION_PARTIALLY_PARSED
                            processedBankStatementVO.statementStatus.message = "Exception occurred during parsing Andhra Bank Current Account statement using pdf2table block====>>>>>> ${e.message}"
                            processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
                            LogEntry.error(processedBankStatementVO.statementStatus.message, e)
                        }
                    }
                    tempCount += 1
                }
            }
            count += 1
            firstTableIndex = -1
            lastTableIndex = -1
        }
        BankUtil.checkForOpeningBalanceTransaction(processedBankStatementVO.bankTransactionList,
                processedBankStatementVO.basicDetails.fromDate?.getTime())
        BankUtil.findFromAndToDate(processedBankStatementVO.bankTransactionList.first(),
                processedBankStatementVO.bankTransactionList.last(), processedBankStatementVO.basicDetails)
    }
}

