package com.bankScraper.bank.pdf

import com.bankScraper.AppUtil
import com.bankScraper.Enums
import com.bankScraper.LogEntry
import com.bankScraper.bank.AndhraBankUtil
import com.bankScraper.bank.BankTransactionUtil
import com.bankScraper.bank.MainBankService
import com.bankScraper.bank.ProcessedBankStatementVO

class AndhraBankPdfService extends MainBankService {

    public void parsePDFStatementForTransactions(ProcessedBankStatementVO processedBankStatementVO) {
        try {
            String fileContent = processedBankStatementVO.processBankStatementCO.textFile.getText("UTF-8").toLowerCase()
            if (fileContent.find("micr") || (fileContent.find("account\\s*statement\\s*(of|for)") && fileContent.find("ifsc\\s*code"))) {
                LogEntry.debug("========== Extracting transactions from Andhra bank account ==========")
                BankTransactionUtil.extractTransactionsFromHTMLHavingDescriptionBelowDate(processedBankStatementVO)
            } else if (fileContent.find("particulars[\\s]*chq[\\s]*no")) {
                LogEntry.debug("========== Extracting transactions from Andhra bank current account ==========")
                AndhraBankUtil.extractTransactionsFromCurrentAccount(processedBankStatementVO)
            }
        } catch (Exception e) {
            processedBankStatementVO.statementStatus.message = "Error occured during parsing pdf file for Andhra bank statement transactions. \n${e.message}"
            processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
            processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.ERROR
            LogEntry.error(processedBankStatementVO.statementStatus.message, e)
        }
    }

}
