package com.bankScraper.bank.pdf

import com.bankScraper.AppUtil
import com.bankScraper.Enums
import com.bankScraper.bank.BankTransactionUtil
import com.bankScraper.bank.KotakBankUtil
import com.bankScraper.bank.MainBankService
import com.bankScraper.bank.ProcessedBankStatementVO
import org.apache.commons.io.FileUtils
import org.apache.commons.lang.StringUtils

class KotakPdfService extends MainBankService {

    //    ========================================= General Methods =================================

    public void resolveBankStatementAccountTypeForBasicDetails(ProcessedBankStatementVO processedBankStatementVO) {
        try {
            File textFile = processedBankStatementVO.processBankStatementCO.textFile
            String fileContent = processedBankStatementVO.processBankStatementCO.textFile.getText("UTF-8")
            List<String> lines = FileUtils.readLines(textFile)
            String titleLine = lines.get(getTitleLineIndex(lines))
            if (fileContent.toLowerCase().find("statement[\\s]*of[\\s]*banking[\\s]*account")) {
                log.debug("=== Parsing Emailed KOTAK Statement ***********")
                KotakBankUtil.extractBasicInformationFromEStatementSavingAccount(processedBankStatementVO)
            } else if (titleLine && titleLine.toLowerCase().contains("account statement")) {
                log.debug("=== Parsing Kotak Current Account Statement ***********")
                KotakBankUtil.extractBasicInformationFromDownloadedCurrentAccount(processedBankStatementVO)
            } else if (fileContent.find("Statement[\\s]*of[\\s]*Account[\\s]*for[\\s]*the[\\s]*Period")) {
                log.debug("===== Parsing Kotak Downloaded Saving Account Type-2 Statement")
                KotakBankUtil.extractBasicInformationFromDownloadedSavingAccountTypeTwo(processedBankStatementVO)
            } else {
                log.debug("=== Parsing Downloaded KOTAK Statement ***********")
                KotakBankUtil.extractBasicInformationFromDownloadedSavingAccount(processedBankStatementVO)
            }
        } catch (Exception e) {
            processedBankStatementVO.statementStatus.message = "Error occured during parsing pdf file for KOTAK bank statement.  ${e.message}"
            processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
            processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.ERROR
            log.error(processedBankStatementVO.statementStatus.message)
            e.printStackTrace()
        }
        log.debug("Original Map ===>>>>   ${processedBankStatementVO.basicDetails.properties}")
    }

    Integer getTitleLineIndex(List<String> lines) {
        Integer titleLineIndex = -1
        for (String line : lines) {
            titleLineIndex++
            if (line && StringUtils.isNotBlank(line) && StringUtils.isNotEmpty(line)) {
                break
            }
        }
        titleLineIndex
    }

    public void parsePDFStatementForTransactions(ProcessedBankStatementVO processedBankStatementVO) {
        File textFile = processedBankStatementVO.processBankStatementCO.textFile
        String fileContent = textFile.getText('UTF-8')
        try {
            Boolean flag = Boolean.FALSE
            Boolean isMergedStatement = Boolean.FALSE
            Boolean downloadedSavingTypeTwo = Boolean.FALSE
            List<String> lines = FileUtils.readLines(textFile)
            String titleLine = lines.get(getTitleLineIndex(lines))
            Scanner scanner = new Scanner(textFile)
            while (scanner.hasNextLine()) {
                String nextToken = scanner.nextLine()
                if (nextToken.equalsIgnoreCase("Statement of Banking Account")) {
                    if (flag) {
                        isMergedStatement = Boolean.TRUE
                        flag = Boolean.FALSE
                        break
                    }
                    flag = Boolean.TRUE
                }
                if (nextToken.find("Statement[\\s]*of[\\s]*Account[\\s]*for[\\s]*the[\\s]*Period")) {
                    downloadedSavingTypeTwo = Boolean.TRUE
                    break
                }
            }
            if (flag || downloadedSavingTypeTwo) {
                log.debug("=== Parsing Emailed KOTAK Statement ***********")
                BankTransactionUtil.extractTransactions(processedBankStatementVO)
            } else if (isMergedStatement) {
                log.debug("=== Parsing Merged Emailed KOTAK Statement ***********")
                KotakBankUtil.extractTransactionsFromMergedEStatementSavingAccount(processedBankStatementVO)
            } else if (titleLine && titleLine.toLowerCase().contains("account statement")) {
//                TODO : Make this condition better
                if (fileContent.toUpperCase().find("[.][\\s]*DATE[\\s]*DESCRIPTION[\\s]*REF/CHQ NO[\\s]*WITH[\\s]*DRAWALS[\\s]*DEPOSITS[\\s]*BALANCES")) {
                    log.debug("=== Parsing Kotak Saving Account Statement Type Three***********")
                    KotakBankUtil.extractTransactionsFromDownloadedSavingAccountTypeThree(processedBankStatementVO)
                } else {
                    log.debug("=== Parsing Kotak Current Account Statement ***********")
                    KotakBankUtil.extractTransactionsFromDownloadedCurrentAccount(processedBankStatementVO)
//                    BankTransactionUtil.extractTransactions(processedBankStatementVO)
                }
            } else {
                log.debug("=== Parsing Downloaded KOTAK Statement ***********")
                BankTransactionUtil.extractTransactions(processedBankStatementVO)
            }
        } catch (Exception e) {
            processedBankStatementVO.statementStatus.message = "Error occured during parsing pdf file for Kotak bank statement transactions.  ${e.message}"
            processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
            processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.ERROR
            log.error(processedBankStatementVO.statementStatus.message)
            e.printStackTrace()
        }
    }
