class BankUtil {

    private static final log = LogFactory.getLog(this)

    public static List<BankTransaction> sortTransactions(List<BankTransaction> bankTransactionList) {
        List<BankTransaction> sortedList = []
        if (bankTransactionList) {
            BankTransaction openingTransaction = bankTransactionList.find() {
                it.transactionCategory == BankTransactionCategory.OPENING_BALANCE || it.description.equals("OPENING BALANCE")
            }
            if (openingTransaction) {
                sortedList.add(openingTransaction)
                bankTransactionList = bankTransactionList - openingTransaction
            }
            bankTransactionList = bankTransactionList.sort() { it.id }
            Map<Date, List<BankTransaction>> transactionMap = bankTransactionList.groupBy { transaction ->
                transaction.dateTime
            }
            Boolean isAscendingOrderList = Boolean.TRUE
            if (transactionMap.size() >= 2) {
                Date firstDate = transactionMap.keySet().getAt(0)
                Date secondDate = transactionMap.keySet().getAt(1)
                Integer comparisonResult = firstDate.compareTo(secondDate)
                if (comparisonResult > 0) {
                    isAscendingOrderList = Boolean.FALSE
                }
            } else if (transactionMap.size() == 1) {
                List<BankTransaction> bankTransactions = transactionMap.getAt(transactionMap.keySet().getAt(0))
                bankTransactions = bankTransactions.sort() { it.id }
                BigDecimal prevBalanceOfLastTransaction = (bankTransactions.last().type == Enums.BankTransactionType.DEBIT ? bankTransactions.last().balanceAfterTransaction + bankTransactions.last().amount : bankTransactions.last().balanceAfterTransaction - bankTransactions.last().amount) as BigDecimal
                prevBalanceOfLastTransaction = HelperMethod.roundTo2Places(prevBalanceOfLastTransaction)
                if (!(prevBalanceOfLastTransaction in bankTransactions*.balanceAfterTransaction)) {
                    isAscendingOrderList = Boolean.FALSE
                }
            }
            transactionMap = transactionMap.sort()
            transactionMap.each { key, value ->
