    static void extractBasicInformationFromDownloadedCurrentAccountType2(ProcessedBankStatementVO processedBankStatementVO) {
        File textFile = processedBankStatementVO.processBankStatementCO.textFile
        if (!AppUtil.isValidStatementFile(textFile, ["ACCOUNT\\s*NO", "ACCOUNT\\s*TYPE", "CUSTOMER\\s*DETAILS", "STATEMENT\\s*OF\\s*ACCOUNT"])) {
            return
        }
        BasicDetailsResponse basicDetailsResponse = processedBankStatementVO.basicDetails
        SimpleDateFormat format = new SimpleDateFormat("dd/MM/yyyy")
        String line = ""
        textFile.withReader("UTF-8") { reader ->
            while ((line = reader.readLine()) != null) {
                if (StringUtils.isBlank(line)) {
                    continue
                } else if (line.find("ACCOUNT\\s*NO\\s*")) {
                    basicDetailsResponse.accountNumber = line.find("[0-9]{15}")?.trim()
                } else if (line.find("CUSTOMER\\s*DETAILS")) {
                    basicDetailsResponse.accountHolderName = line.split(":")[1]?.trim()
                } else if (line.find("STATEMENT\\s*OF\\s*ACCOUNT\\s*from")) {
                    List<String> dateList = line.findAll("[0-3]?[0-9]/[0-3]?[0-9]/(?:[0-9]{2})?[0-9]{2}")
                    if (dateList.size() == 2) {
                        String fromDate = dateList.get(0)
                        String toDate = dateList.get(1)
                        basicDetailsResponse.fromDate = format.parse(fromDate).toCalendar()
                        basicDetailsResponse.toDate = format.parse(toDate).toCalendar()
                    }
                    break
                }
            }
        }
        processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.PARTIALLY_PARSED
        processedBankStatementVO.statementStatus.message = "Basic details extracted Successfully"
    }
