    public static void addCreditOrDebitAndBalanceForTransaction(ProcessedBankStatementVO processedBankStatementVO) {
        List<BankTransactionResponse> bankTransactionList = processedBankStatementVO.bankTransactionList
        BankTransactionResponse bankTransactionResponse = bankTransactionList.remove(0)
        if (bankTransactionList.first().transactionDate.compareTo(bankTransactionList.last().transactionDate) > 0) {
            bankTransactionList = bankTransactionList.reverse()
        }
        bankTransactionList.add(0, bankTransactionResponse)
        for (int i = 1; i < bankTransactionList.size(); i++) {
            bankTransactionResponse = bankTransactionList.get(i)
            if (bankTransactionResponse.amount == null && bankTransactionResponse.balanceAfterTransaction != null && bankTransactionResponse.balanceAfterTransaction > bankTransactionList.get(i - 1).balanceAfterTransaction) {
                bankTransactionList.get(i).amount = bankTransactionResponse.balanceAfterTransaction - bankTransactionList.get(i - 1).balanceAfterTransaction
                bankTransactionList.get(i).type = Enums.BankTransactionType.CREDIT
            } else if (bankTransactionResponse.amount == null && bankTransactionResponse.balanceAfterTransaction != null && bankTransactionResponse.balanceAfterTransaction < bankTransactionList.get(i - 1).balanceAfterTransaction) {
                bankTransactionList.get(i).amount = bankTransactionList.get(i - 1).balanceAfterTransaction - bankTransactionResponse.balanceAfterTransaction
                bankTransactionList.get(i).type = Enums.BankTransactionType.DEBIT
            } else if ((bankTransactionResponse.amount == null && bankTransactionResponse.balanceAfterTransaction == null) || (bankTransactionResponse.amount == 0D && bankTransactionResponse.balanceAfterTransaction == 0.00)) {
                bankTransactionList.get(i).amount = 0
                bankTransactionList.get(i).type = Enums.BankTransactionType.CREDIT
                bankTransactionList.get(i).balanceAfterTransaction = bankTransactionList.get(i - 1).balanceAfterTransaction
            } else if (bankTransactionResponse.amount != null && (bankTransactionResponse.balanceAfterTransaction == 0.00 || bankTransactionResponse.balanceAfterTransaction == null)) {
                bankTransactionList.get(i).balanceAfterTransaction = bankTransactionResponse.type == Enums.BankTransactionType.DEBIT ?
                        bankTransactionList.get(i - 1).balanceAfterTransaction - bankTransactionResponse.amount :
                        bankTransactionList.get(i - 1).balanceAfterTransaction + bankTransactionResponse.amount
            }
        }
        processedBankStatementVO.bankTransactionList = bankTransactionList
    }

