/**
 * Parses the transaction date of a row after normalizing it. A row which does not carry a date of its own
 * (or carries an unparsable one) inherits the date of the previously parsed transaction.
 */
    public static Date resolveTransactionDate(String dateValue, ProcessedBankStatementVO processedBankStatementVO) {
        String date = dateValue ? processValue(dateValue.trim()) : ""
        if (date) {
            try {
                return dateFormatFromString(date).parse(date)
            } catch (Exception e) {
                log.debug("Unable to parse transaction date '${dateValue}', date of the previous transaction will be used.")
            }
        }
        return processedBankStatementVO.bankTransactionList ? processedBankStatementVO.bankTransactionList.last().transactionDate : null
    }

