/**
 * Parses a transaction date of a statement. The date is first parsed as it is present in the statement and if that
 * fails it gets normalized(spaces/hyphens/wrongly extracted month names) and parsed again.
 * eg: '03- JUL- 2017' and '03-JUY-2017' both are parsed as 3rd July 2017
 */
    public static Date parseTransactionDate(String dateValue) {
        if (!dateValue || !dateValue.trim()) {
            return null
        }
        List<String> dateValues = [dateValue.trim(), processValue(dateValue.trim())].unique()
        for (String date : dateValues) {
            try {
                return dateFormatFromString(date).parse(date)
            } catch (Exception e) {
                log.debug("Unable to parse the date '${date}' of the statement.")
            }
        }
        return null
    }

/**
 * Parses the transaction date of a row. A row which does not carry a date of its own (or carries an unparsable one)
 * inherits the date of the previously parsed transaction.
 */
    public static Date resolveTransactionDate(String dateValue, ProcessedBankStatementVO processedBankStatementVO) {
        Date transactionDate = parseTransactionDate(dateValue)
        if (transactionDate) {
            return transactionDate
        }
        return processedBankStatementVO.bankTransactionList ? processedBankStatementVO.bankTransactionList.last().transactionDate : null
    }

    public static Date resolveValueDate(String dateValue) {
        parseTransactionDate(dateValue)
    }

